comments.body:
Nit: There's now a lot of `'a'` and `'b'`. Maybe `check_diff` can just accept the `&Path` and then do everything itself. This would de-dupl a bunch of code. Something like this (untested):

```diff
 contrib/devtools/deterministic-fuzz-coverage/src/main.rs | 48 +++++++++++++++++++++---------------------------
 1 file changed, 21 insertions(+), 27 deletions(-)

diff --git a/contrib/devtools/deterministic-fuzz-coverage/src/main.rs b/contrib/devtools/deterministic-fuzz-coverage/src/main.rs
index d536cf1..5859d7e 100644
--- a/contrib/devtools/deterministic-fuzz-coverage/src/main.rs
+++ b/contrib/devtools/deterministic-fuzz-coverage/src/main.rs
@@ -216,7 +216,18 @@ fn deterministic_coverage(
         };
-    let check_diff = |a: &Path, b: &Path, err: &str| -> AppResult {
+    let check_diff = |entry: &Path, thread_id: usize, err: &str| -> AppResult {
+        let profdata_base = run_profile('a', entry, thread_id)?;
+        let profdata_repeat = run_profile('b', entry, thread_id)?;
+        // Fast path: identical counters mean the coverage is deterministic, so
+        // skip the expensive llvm-cov rendering entirely.
+        if profdata_eq(&profdata_base, &profdata_repeat)? {
+            return Ok(());
+        }
+        // Slow path: the profiles differ, so render both into human-readable
+        // reports and diff them to confirm and locate the difference.
+        let cov_txt_base = render_cov(&profdata_base, 'a', thread_id)?;
+        let cov_txt_repeat = render_cov(&profdata_repeat, 'b', thread_id)?;
         let same = Command::new(GIT)
             .args(["--no-pager", "diff", "--no-index"])
-            .arg(a)
-            .arg(b)
+            .arg(&cov_txt_base)
+            .arg(&cov_txt_repeat)
             .status()
@@ -249,16 +260,5 @@ The coverage was not deterministic between runs.
         }
-        let profdata_base = run_profile('a', &entry, thread_id)?;
-        let profdata_repeat = run_profile('b', &entry, thread_id)?;
-        // Fast path: identical counters mean the coverage is deterministic, so
-        // skip the expensive llvm-cov rendering entirely.
-        if profdata_eq(&profdata_base, &profdata_repeat)? {
-            return Ok(());
-        }
-        // Slow path: the profiles differ, so render both into human-readable
-        // reports and diff them to confirm and locate the difference.
-        let cov_txt_base = render_cov(&profdata_base, 'a', thread_id)?;
-        let cov_txt_repeat = render_cov(&profdata_repeat, 'b', thread_id)?;
         check_diff(
-            &cov_txt_base,
-            &cov_txt_repeat,
+            &entry,
+            thread_id,
             &format!("The fuzz target input was {}.", entry.display()),
@@ -297,13 +297,7 @@ The coverage was not deterministic between runs.
         }
-        let profdata_base = run_profile('a', &corpus_dir, 0)?;
-        let profdata_repeat = run_profile('b', &corpus_dir, 0)?;
-        if !profdata_eq(&profdata_base, &profdata_repeat)? {
-            let cov_txt_base = render_cov(&profdata_base, 'a', 0)?;
-            let cov_txt_repeat = render_cov(&profdata_repeat, 'b', 0)?;
-            check_diff(
-                &cov_txt_base,
-                &cov_txt_repeat,
-                &format!("All fuzz inputs in {} were used.", corpus_dir.display()),
-            )?;
-        }
+        check_diff(
+            &corpus_dir,
+            0,
+            &format!("All fuzz inputs in {} were used.", corpus_dir.display()),
+        )?;
     }
```

Possibly could also inline `profdata_eq` and only keep a small comment as it is only called once, to save some more lines?
